package subtitle

import (
	"strings"
	"testing"
)

func TestParseVTTValid(t *testing.T) {
	in := "WEBVTT\n\n" +
		"NOTE generated by test\n\n" +
		"cue-1\n00:00:01.000 --> 00:00:02.500 align:start position:0%\nhello\n\n" +
		"00:03.000 --> 00:04.000\nworld\n"
	rep := ParseVTT(strings.NewReader(in), testTB())
	if len(rep.Rejected) != 0 {
		t.Fatalf("unexpected rejects: %+v", rep.Rejected)
	}
	if len(rep.Records) != 2 {
		t.Fatalf("got %d records", len(rep.Records))
	}
	r := rep.Records[0]
	if r.StartRaw != "00:00:01.000" || r.Source != "vtt" || r.Line != 6 {
		t.Fatalf("bad record: %+v", r)
	}
	if r.Start != 30 || r.End != 75 {
		t.Fatalf("frames = %d..%d", r.Start, r.End)
	}
	if rep.Records[1].Start != 90 {
		t.Fatalf("MM:SS.mmm form: start = %d, want 90", rep.Records[1].Start)
	}
}

func TestParseVTTNoHeader(t *testing.T) {
	rep := ParseVTT(strings.NewReader("00:00:01.000 --> 00:00:02.000\nx\n"), testTB())
	if len(rep.Records) != 0 || len(rep.Rejected) != 1 || rep.Rejected[0].Line != 1 {
		t.Fatalf("got %+v", rep)
	}
}

func TestParseVTTBadCueAndTruncation(t *testing.T) {
	in := "WEBVTT\n\n" +
		"00:00:01.000 --> 00:00:02.000\nok\n\n" +
		"00:00:xx.000 --> 00:00:03.000\nbad\n\n" +
		"lonely-identifier\n"
	rep := ParseVTT(strings.NewReader(in), testTB())
	if len(rep.Records) != 1 {
		t.Fatalf("got %d records", len(rep.Records))
	}
	if len(rep.Rejected) != 2 {
		t.Fatalf("rejects = %+v, want 2", rep.Rejected)
	}
	if rep.Rejected[0].Line != 6 || rep.Rejected[1].Line != 9 {
		t.Fatalf("reject lines = %+v", rep.Rejected)
	}
}
